import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:cicadaos/core/crypto/box.dart';
import 'package:cicadaos/core/crypto/key_store.dart';
import 'package:cicadaos/core/crypto/signer.dart';
import 'package:cicadaos/core/hex.dart';
import 'package:cicadaos/core/protocol.dart';
import 'package:cryptography/cryptography.dart';
import 'package:flutter_test/flutter_test.dart';

/// Proves the Dart v2 frame builder agrees byte-for-byte with the firmware. The
/// vectors are generated by ../firmware/tools/make_vectors.py using Ed25519 from
/// the `cryptography` package and X25519 / BLAKE2b / XChaCha20-Poly1305 from
/// firmware/cryptobox.py (whose primitives are cross-checked against reference
/// implementations). Each vector pins the ephemeral scalar and AEAD nonce so the
/// otherwise-randomised frame is reproducible.
void main() {
  final vectorsFile = File('tools_vectors/vectors.json');
  final doc = jsonDecode(vectorsFile.readAsStringSync()) as Map<String, dynamic>;
  final seedHex = doc['seed'] as String;
  final pubkeyHex = doc['pubkey'] as String;
  final devicePub = hexDecode(doc['device_x25519_pub'] as String);
  final vectors = (doc['vectors'] as List).cast<Map<String, dynamic>>();

  test('vectors file is present, v2, non-trivial', () {
    expect(vectors.length, greaterThanOrEqualTo(4));
    expect(doc['domain'], 'espscript-v1');
    expect(doc['version'], 0x02);
    expect(devicePub.length, 32);
  });

  group('v2 frame byte-equality with firmware', () {
    late Signer signer;
    late ScriptSealer sealer;
    setUp(() {
      signer = Signer(InMemoryKeyStore(seedHex));
      sealer = ScriptSealer(signer);
    });

    test('public key matches the vectors', () async {
      expect(await signer.publicKeyHex(), pubkeyHex);
    });

    for (final v in vectors) {
      test('frame matches for "${v['name']}"', () async {
        final nonce = hexDecode(v['nonce'] as String);
        final aeadNonce = hexDecode(v['aead_nonce'] as String);
        final script = Uint8List.fromList(utf8.encode(v['script'] as String));
        final ephemeral =
            await X25519().newKeyPairFromSeed(hexDecode(v['eph_priv'] as String));

        // Sanity: the ephemeral public key matches too.
        final ephPub = (await ephemeral.extractPublicKey()).bytes;
        expect(hexEncode(ephPub), v['eph_pub'],
            reason: 'X25519 ephemeral public key mismatch');

        final frame = await sealer.seal(script, nonce, devicePub,
            ephemeral: ephemeral, aeadNonce: aeadNonce);
        // frame = [len BE4][frame_body]; the vector stores the body.
        expect(hexEncode(frame.sublist(4)), v['frame_body'],
            reason: 'frame mismatch is the classic ERR:sig cause');
      });
    }
  });

  group('key lifecycle', () {
    test('generate-once persists and is stable across calls', () async {
      final store = InMemoryKeyStore();
      final signer = Signer(store);
      expect(await signer.hasKey(), isFalse);
      final pk1 = await signer.publicKeyHex();
      expect(await signer.hasKey(), isTrue);
      final pk2 = await Signer(store).publicKeyHex(); // reload from store
      expect(pk1, pk2);
    });

    test('reset clears the identity', () async {
      final store = InMemoryKeyStore();
      final signer = Signer(store);
      await signer.ensureKey();
      await signer.reset();
      expect(await signer.hasKey(), isFalse);
    });

    test('private seed is 32 bytes and distinct from the public key', () async {
      final store = InMemoryKeyStore();
      await Signer(store).ensureKey();
      final seed = hexDecode((await store.readSeedHex())!);
      expect(seed.length, 32);
      final pub = hexDecode(await Signer(store).publicKeyHex());
      expect(hexEncode(seed), isNot(hexEncode(pub)));
    });
  });

  group('frame + nonce helpers', () {
    test('v2Frame prefixes big-endian length of the body', () {
      final ephPub = Uint8List(32)..[0] = 0xEE;
      final aeadNonce = Uint8List(24)..[0] = 0xAA;
      final ct = Uint8List.fromList([1, 2, 3, 4, 5]);
      final mac = Uint8List(16)..[0] = 0xCC;
      final sig = Uint8List(64)..[0] = 0xAB;
      final frame = Protocol.v2Frame(ephPub, aeadNonce, ct, mac, sig);
      final bodyLen = 32 + 24 + 5 + 16 + 64;
      final len = ByteData.sublistView(frame, 0, 4).getUint32(0, Endian.big);
      expect(len, bodyLen);
      expect(frame.length, 4 + bodyLen);
    });

    test('v2Frame rejects wrong-length components', () {
      expect(
          () => Protocol.v2Frame(Uint8List(31), Uint8List(24), Uint8List(0),
              Uint8List(16), Uint8List(64)),
          throwsArgumentError);
      expect(
          () => Protocol.v2Frame(Uint8List(32), Uint8List(24), Uint8List(0),
              Uint8List(16), Uint8List(63)),
          throwsArgumentError);
    });

    test('isValidNonce rejects all-zero and wrong length', () {
      expect(Protocol.isValidNonce(Uint8List(32)), isFalse);
      expect(Protocol.isValidNonce(Uint8List(31)), isFalse);
      expect(Protocol.isValidNonce(Uint8List(32)..[5] = 1), isTrue);
    });
  });
}
